// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.decimal;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.integer;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.str;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import java.math.BigInteger;
import java.time.ZoneOffset;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of {@code dtf:epoch}, {@code dtf:epochMillis}, {@code dtf:fromUnixtime} and {@code dtf:fromEpochMillis}.
 */
class EpochAndUnixtimeEdgeCaseTest {

	private final Epoch epoch = new Epoch();
	private final EpochMillis epochMillis = new EpochMillis();
	private final FromUnixtime fromUnixtime = new FromUnixtime();
	private final FromEpochMillis fromEpochMillis = new FromEpochMillis();

	// epoch, epochMillis

	@Test
	void valuesBefore1970AreNegativeAndEpochKeepsFractionalSeconds() {
		assertThat(epoch.evaluate(VF, dt("1969-12-31T23:59:59Z"))).isEqualTo(decimal("-1"));
		Literal half = epoch.evaluate(VF, dt("1969-12-31T23:59:59.5Z"));
		assertThat(half).isEqualTo(decimal("-0.5"));
		assertThat(half.getDatatype()).isEqualTo(CoreDatatype.XSD.DECIMAL.getIri());
		assertThat(epoch.evaluate(VF, dt("1970-01-01T00:00:00.123456789Z"))).isEqualTo(decimal("0.123456789"));
		assertThat(epochMillis.evaluate(VF, dt("1969-12-31T23:59:59Z"))).isEqualTo(integer(-1000));
		assertThat(epochMillis.evaluate(VF, dt("1970-01-01T00:00:00Z")).getDatatype())
				.isEqualTo(CoreDatatype.XSD.INTEGER.getIri());
	}

	@Test
	void inputWithoutTimezoneIsTreatedAsUtc() {
		// pins current behaviour (class Javadoc): no timezone means UTC, not an error and not the JVM default zone
		assertThat(epoch.evaluate(VF, dt("1970-01-01T01:00:00"))).isEqualTo(decimal("3600"));
		assertThat(epoch.evaluate(VF, dt("1970-01-01T01:00:00")))
				.isEqualTo(epoch.evaluate(VF, dt("1970-01-01T01:00:00Z")));
		assertThat(epochMillis.evaluate(VF, dt("1970-01-01T01:00:00"))).isEqualTo(integer(3_600_000L));
	}

	@Test
	void datesAreMidnightAndTimesAreAnEvaluationError() {
		assertThat(epoch.evaluate(VF, date("1970-01-02"))).isEqualTo(decimal("86400"));
		// a date with a timezone is midnight in that timezone
		assertThat(epoch.evaluate(VF, date("1970-01-02+02:00"))).isEqualTo(decimal("79200"));
		assertThat(epochMillis.evaluate(VF, date("1969-12-31"))).isEqualTo(integer(-86_400_000L));
		assertEvaluationError("epoch(time)", () -> epoch.evaluate(VF, time("10:00:00Z")));
		assertEvaluationError("epochMillis(time)", () -> epochMillis.evaluate(VF, time("10:00:00Z")));
	}

	@Test
	void epochMillisTruncatesSubMillisecondDigitsTowardsNegativeInfinity() {
		// pins current behaviour (Instant.toEpochMilli): floor, not rounding
		assertThat(epochMillis.evaluate(VF, dt("1970-01-01T00:00:00.0019Z"))).isEqualTo(integer(1));
		assertThat(epochMillis.evaluate(VF, dt("1970-01-01T00:00:00.9999Z"))).isEqualTo(integer(999));
		assertThat(epochMillis.evaluate(VF, dt("1969-12-31T23:59:59.9995Z"))).isEqualTo(integer(-1));
		assertThat(epochMillis.evaluate(VF, dt("1969-12-31T23:59:59.9999999Z"))).isEqualTo(integer(-1));
	}

	// fromUnixtime, fromEpochMillis

	@Test
	void negativeZeroDecimalAndVeryLargeSeconds() {
		assertThat(fromUnixtime.evaluate(VF, integer(0))).isEqualTo(dt("1970-01-01T00:00:00Z"));
		assertThat(fromUnixtime.evaluate(VF, integer(-86_400))).isEqualTo(dt("1969-12-31T00:00:00Z"));
		assertThat(fromUnixtime.evaluate(VF, decimal("1.5"))).isEqualTo(dt("1970-01-01T00:00:01.5Z"));
		assertThat(fromUnixtime.evaluate(VF, decimal("-1.5"))).isEqualTo(dt("1969-12-31T23:59:58.5Z"));
		assertThat(fromUnixtime.evaluate(VF, decimal("0.000000001"))).isEqualTo(dt("1970-01-01T00:00:00.000000001Z"));
		// pins current behaviour: the ECMAScript limit (year 275760) is well inside java.time's range, so it is
		// accepted; the last representable second is the end of year 999999999 and one second more is an error
		assertThat(fromUnixtime.evaluate(VF, integer(8_640_000_000_000L))).isEqualTo(dt("275760-09-13T00:00:00Z"));
		assertThat(fromUnixtime.evaluate(VF, integer(31_556_889_832_780_799L)))
				.isEqualTo(dt("999999999-12-31T23:59:59Z"));
		assertEvaluationError("one second past the last year",
				() -> fromUnixtime.evaluate(VF, integer(31_556_889_832_780_800L)));
		assertThat(fromEpochMillis.evaluate(VF, integer(0))).isEqualTo(dt("1970-01-01T00:00:00Z"));
		assertThat(fromEpochMillis.evaluate(VF, integer(-1))).isEqualTo(dt("1969-12-31T23:59:59.999Z"));
		assertThat(fromEpochMillis.evaluate(VF, integer(1500))).isEqualTo(dt("1970-01-01T00:00:01.5Z"));
		assertThat(fromEpochMillis.evaluate(VF, integer(8_640_000_000_000_000L)))
				.isEqualTo(dt("275760-09-13T00:00:00Z"));
		assertEvaluationError("millis beyond long",
				() -> fromEpochMillis.evaluate(VF, VF.createLiteral(BigInteger.TWO.pow(64))));
	}

	@Test
	void resultIsAnXsdDateTimeInUtc() {
		for (Literal result : List.of(fromUnixtime.evaluate(VF, integer(1_715_940_672L)),
				fromUnixtime.evaluate(VF, decimal("-0.25")),
				fromEpochMillis.evaluate(VF, integer(1_715_940_672_250L)))) {
			assertThat(result.getDatatype()).isEqualTo(CoreDatatype.XSD.DATETIME.getIri());
			assertThat(result.getLabel()).endsWith("Z");
			assertThat(DateTimeSupport.parse(result.getLabel(), DateTimeSupport.Kind.DATE_TIME).offset())
					.isEqualTo(ZoneOffset.UTC);
		}
	}

	@Test
	void epochAndFromUnixtimeRoundTripForUtcInput() {
		for (String lexical : List.of("2024-05-17T10:11:12.25Z", "1969-07-20T20:17:40Z", "0001-01-01T00:00:00Z",
				"2024-05-17T10:11:12.123456789Z", "9999-12-31T23:59:59.999Z")) {
			Literal value = dt(lexical);
			assertThat(fromUnixtime.evaluate(VF, epoch.evaluate(VF, value))).as(lexical).isEqualTo(value);
		}
		Literal millis = dt("2024-05-17T10:11:12.25Z");
		assertThat(fromEpochMillis.evaluate(VF, epochMillis.evaluate(VF, millis))).isEqualTo(millis);
		// pins current behaviour: a non-Z offset round-trips to the same instant written with Z
		assertThat(fromUnixtime.evaluate(VF, epoch.evaluate(VF, dt("2024-05-17T12:11:12+02:00"))))
				.isEqualTo(dt("2024-05-17T10:11:12Z"));
	}

	@Test
	void nonNumericAndNonFiniteInputsAreAnEvaluationError() {
		assertEvaluationError("plain string", () -> fromUnixtime.evaluate(VF, str("0")));
		assertEvaluationError("xsd:string", () -> fromUnixtime.evaluate(VF,
				VF.createLiteral("0", CoreDatatype.XSD.STRING)));
		assertEvaluationError("malformed integer", () -> fromUnixtime.evaluate(VF,
				VF.createLiteral("abc", CoreDatatype.XSD.INTEGER)));
		for (double special : new double[] { Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY }) {
			assertEvaluationError("double " + special, () -> fromUnixtime.evaluate(VF, VF.createLiteral(special)));
		}
		for (float special : new float[] { Float.NaN, Float.POSITIVE_INFINITY }) {
			assertEvaluationError("float " + special, () -> fromUnixtime.evaluate(VF, VF.createLiteral(special)));
		}
		// finite doubles are fine
		assertThat(fromUnixtime.evaluate(VF, VF.createLiteral(1.5d))).isEqualTo(dt("1970-01-01T00:00:01.5Z"));
		// pins current behaviour: fromEpochMillis only accepts integer-typed literals
		assertEvaluationError("decimal millis", () -> fromEpochMillis.evaluate(VF, decimal("1.5")));
		assertEvaluationError("double millis", () -> fromEpochMillis.evaluate(VF, VF.createLiteral(1000.0d)));
		assertEvaluationError("string millis", () -> fromEpochMillis.evaluate(VF, str("1000")));
	}
}
